--
-- Table structure for table `purchase_request_detail`
--

DROP TABLE IF EXISTS `purchase_request_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `purchase_request_detail` (
  `pr_detail_id` int(11) NOT NULL AUTO_INCREMENT,
  `pr_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `requested_qty` int(11) NOT NULL,
  `approved_qty` int(11) DEFAULT NULL,
  `adjustment_reason` varchar(255) DEFAULT NULL,
  `ordered_qty` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`pr_detail_id`),
  UNIQUE KEY `uq_prd_pr_product` (`pr_id`,`product_id`),
